mkdir -p src test; cat > src/host.impl.ts <<'EOF'
// T9: electing a leader among three nodes, single round (term 1).

export interface Message {
  id: string;
  from: string;
  to: string;
  action: string;
  data: Record<string, unknown>;
}

export type Outcome = { ok: true } | { ok: false; reason: string };

export interface NodeView {
  role: 'follower' | 'candidate' | 'leader';
  term: number;
  votedFor: string | null;
}

export interface Host {
  inFlight(): Promise<Message[]>;
  deliver(id: string): Promise<void>;
  deliverAll(): Promise<void>;
  timeout(node: string): Promise<Outcome>;
  node(node: string): Promise<NodeView | null>;
}

const NODE_IDS = ['n0', 'n1', 'n2'] as const;
const MAJORITY = 2;
const ELECTION_TERM = 1;

interface NodeState {
  id: string;
  role: 'follower' | 'candidate' | 'leader';
  term: number;
  votedFor: string | null;
  votes: Set<string>;
}

export default async function createHost(): Promise<Host> {
  const nodes = new Map<string, NodeState>();
  for (const id of NODE_IDS) {
    nodes.set(id, { id, role: 'follower', term: 0, votedFor: null, votes: new Set() });
  }
  const transit = new Map<string, Message>();
  let nextId = 1;

  function send(from: string, to: string, action: string, data: Record<string, unknown>): void {
    const id = `m${nextId++}`;
    transit.set(id, { id, from, to, action, data });
  }

  function onRequestVote(n: NodeState, msg: Message): void {
    const candidate = msg.data.from;
    const term = msg.data.term;
    if (typeof candidate !== 'string' || !nodes.has(candidate) || candidate === n.id) return;
    if (term !== ELECTION_TERM) return;
    let granted = false;
    if (n.term === 0) {
      n.term = ELECTION_TERM;
      n.role = 'follower';
      n.votedFor = candidate;
      granted = true;
    } else if (n.term === ELECTION_TERM) {
      granted = n.role === 'follower' && (n.votedFor === null || n.votedFor === candidate);
      if (granted) n.votedFor = candidate;
    }
    send(n.id, candidate, 'VoteReply', { term: ELECTION_TERM, granted });
  }

  function onVoteReply(n: NodeState, msg: Message): void {
    if (n.role !== 'candidate') return;
    if (msg.data.term !== n.term || msg.data.granted !== true) return;
    n.votes.add(msg.from);
    if (n.votes.size >= MAJORITY) n.role = 'leader';
  }

  function deliverOne(id: string): void {
    const msg = transit.get(id);
    if (!msg) return;
    transit.delete(id);
    const n = nodes.get(msg.to);
    if (!n) return;
    if (msg.action === 'RequestVote') onRequestVote(n, msg);
    else if (msg.action === 'VoteReply') onVoteReply(n, msg);
  }

  return {
    async inFlight() {
      return [...transit.values()].map((m) => ({ ...m, data: { ...m.data } }));
    },
    async deliver(id: string) {
      deliverOne(id);
    },
    async deliverAll() {
      while (transit.size > 0) {
        const id = transit.keys().next().value as string;
        deliverOne(id);
      }
    },
    async timeout(id: string): Promise<Outcome> {
      const n = nodes.get(id);
      if (!n) return { ok: false, reason: `unknown node: ${id}` };
      if (n.role !== 'follower' || n.term !== 0) {
        return { ok: false, reason: `${id} cannot start an election: it is a ${n.role} in term ${n.term}` };
      }
      n.role = 'candidate';
      n.term = ELECTION_TERM;
      n.votedFor = id;
      n.votes = new Set([id]);
      for (const other of NODE_IDS) {
        if (other !== id) send(id, other, 'RequestVote', { from: id, term: ELECTION_TERM });
      }
      return { ok: true };
    },
    async node(id: string) {
      const n = nodes.get(id);
      if (!n) return null;
      return { role: n.role, term: n.term, votedFor: n.votedFor };
    },
  };
}
EOF
cat > test/host.test.ts <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('single candidate wins', async () => {
  const h = await createHost();
  assert.deepEqual(await h.timeout('n0'), { ok: true });
  assert.equal((await h.timeout('n0')).ok, false);
  assert.equal((await h.timeout('x')).ok, false);
  assert.equal(await h.node('x'), null);
  const m = await h.inFlight();
  assert.equal(m.length, 2);
  assert.deepEqual(m[0].data, { from: 'n0', term: 1 });
  await h.deliverAll();
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0' });
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 1, votedFor: 'n0' });
  assert.equal((await h.timeout('n1')).ok, false);
});

async function randomRun(seed: number) {
  let s = seed;
  const rnd = () => ((s = (s * 1103515245 + 12345) % 2147483648) / 2147483648);
  const h = await createHost();
  const ids = ['n0', 'n1', 'n2'];
  for (;;) {
    const fl = await h.inFlight();
    const opts = ids.length + fl.length;
    if (opts === 0) break;
    const k = Math.floor(rnd() * opts);
    if (k < ids.length) { await h.timeout(ids[k]); ids.splice(k, 1); }
    else await h.deliver(fl[k - ids.length].id);
  }
  const views = await Promise.all(['n0', 'n1', 'n2'].map((n) => h.node(n)));
  const leaders = views.map((v, i) => [v!, `n${i}`] as const).filter(([v]) => v.role === 'leader');
  assert.ok(leaders.length <= 1);
  for (const [, id] of leaders) assert.ok(views.filter((v) => v!.votedFor === id).length >= 2);
}

test('random orders: safety', async () => {
  for (let i = 1; i < 2000; i++) await randomRun(i);
});
EOF
npx tsc --noEmit --strict --target esnext --module nodenext --allowImportingTsExtensions src/host.impl.ts test/host.test.ts && npm test 2>&1 | tail -12

