import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('single candidate wins', async () => {
  const h = await createHost();
  assert.deepEqual(await h.timeout('n0'), { ok: true });
  assert.equal((await h.timeout('n0')).ok, false);
  assert.equal((await h.timeout('x')).ok, false);
  assert.equal(await h.node('x'), null);
  const m = await h.inFlight();
  assert.equal(m.length, 2);
  assert.deepEqual(m[0].data, { from: 'n0', term: 1 });
  await h.deliverAll();
  assert.deepEqual(await h.node('n0'), { role: 'leader', term: 1, votedFor: 'n0', leader: 'n0' });
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 1, votedFor: 'n0', leader: 'n0' });
  assert.equal((await h.timeout('n1')).ok, false);
});

async function randomRun(seed: number) {
  let s = seed;
  const rnd = () => (s = (s * 1103515245 + 12345) % 2147483648) / 2147483648;
  const h = await createHost();
  const ids = ['n0', 'n1', 'n2'];
  for (;;) {
    const fl = await h.inFlight();
    const opts = ids.length + fl.length;
    if (opts === 0) break;
    if (rnd() < 0.1) await h.giveUp(['n0', 'n1', 'n2'][Math.floor(rnd() * 3)]);
    const k = Math.floor(rnd() * opts);
    if (k < ids.length) {
      await h.timeout(ids[k]);
      ids.splice(k, 1);
    } else await h.deliver(fl[k - ids.length].id);
  }
  const views = await Promise.all(['n0', 'n1', 'n2'].map((n) => h.node(n)));
  const leaders = ['n0', 'n1', 'n2'].filter((_, i) => views[i]!.role === 'leader');
  assert.ok(leaders.length <= 1);
  for (const id of leaders) assert.ok(views.filter((v) => v!.votedFor === id).length >= 2);
  for (const v of views) if (v!.leader !== null) assert.deepEqual([v!.leader], leaders);
  if (leaders.length) for (const v of views) assert.equal(v!.leader, leaders[0]);
}

test('random orders: safety', async () => {
  for (let i = 1; i < 2000; i++) await randomRun(i);
});

test('candidate steps down on Leader; term-0 node learns leader without voting', async () => {
  const h = await createHost();
  await h.timeout('n0');
  await h.timeout('n1');
  // n0's RequestVote to n2 -> n2 votes n0
  const toN2 = (await h.inFlight()).find((m) => m.from === 'n0' && m.to === 'n2')!;
  await h.deliver(toN2.id);
  const reply = (await h.inFlight()).find((m) => m.action === 'VoteReply')!;
  await h.deliver(reply.id);
  assert.equal((await h.node('n0'))!.role, 'leader');
  const ann = (await h.inFlight()).filter((m) => m.action === 'Leader');
  assert.equal(ann.length, 2);
  assert.deepEqual(ann[0].data, { from: 'n0', term: 1 });
  await h.deliver(ann.find((m) => m.to === 'n1')!.id);
  assert.deepEqual(await h.node('n1'), { role: 'follower', term: 1, votedFor: 'n1', leader: 'n0' });

  const h2 = await createHost();
  await h2.timeout('n0');
  await h2.deliver((await h2.inFlight()).find((m) => m.to === 'n1')!.id);
  await h2.deliver((await h2.inFlight()).find((m) => m.action === 'VoteReply')!.id);
  await h2.deliver((await h2.inFlight()).find((m) => m.action === 'Leader' && m.to === 'n2')!.id);
  assert.deepEqual(await h2.node('n2'), { role: 'follower', term: 1, votedFor: null, leader: 'n0' });
  assert.deepEqual(await h2.node('n0'), { role: 'leader', term: 1, votedFor: 'n0', leader: 'n0' });
});

test('giveUp: candidate becomes follower, keeps self vote, ignores late replies', async () => {
  const h = await createHost();
  assert.equal((await h.giveUp('n0')).ok, false);
  assert.equal((await h.giveUp('zz')).ok, false);
  await h.timeout('n0');
  await h.deliver((await h.inFlight()).find((m) => m.to === 'n1')!.id);
  assert.deepEqual(await h.giveUp('n0'), { ok: true });
  assert.equal((await h.giveUp('n0')).ok, false);
  assert.equal((await h.timeout('n0')).ok, false);
  await h.deliver((await h.inFlight()).find((m) => m.action === 'VoteReply')!.id);
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
  // n2 runs; n0 refuses its vote, n1 already voted for n0 -> n2 cannot win
  await h.timeout('n2');
  await h.deliverAll();
  assert.deepEqual(await h.node('n2'), { role: 'candidate', term: 1, votedFor: 'n2', leader: null });
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: null });
});

