async function randomRun(seed: number) {
  let s = seed;
  const rnd = () => (s = (s * 1103515245 + 12345) % 2147483648) / 2147483648;
  const h = await createHost();
  const ids = ['n0', 'n1', 'n2'];
  for (;;) {
    const fl = await h.inFlight();
    const opts = ids.length + fl.length;
    if (opts === 0) break;
    if (rnd() < 0.1) await h.giveUp(['n0', 'n1', 'n2'][Math.floor(rnd() * 3)]);
    if (rnd() < 0.1) await h.crash(['n0', 'n1', 'n2'][Math.floor(rnd() * 3)]);
    if (rnd() < 0.1) await h.recover(['n0', 'n1', 'n2'][Math.floor(rnd() * 3)]);
    const k = Math.floor(rnd() * opts);
    if (k < ids.length) {
      await h.timeout(ids[k]);
      ids.splice(k, 1);
    } else await h.deliver(fl[k - ids.length].id);
  }
  const views = await Promise.all(['n0', 'n1', 'n2'].map((n) => h.node(n)));
  const leaders = ['n0', 'n1', 'n2'].filter((_, i) => views[i]!.role === 'leader');
  assert.ok(leaders.length <= 1);
  for (const id of leaders) assert.ok(views.filter((v) => v!.votedFor === id).length >= 2);
  for (const v of views) if (v!.leader !== null) assert.deepEqual([v!.leader], leaders);
  if (leaders.length) for (const v of views) assert.equal(v!.leader, leaders[0]);
}

test('random orders: safety', async () => {
  for (let i = 1; i < 2000; i++) await randomRun(i);
});

