const ALL = ['n0', 'n1', 'n2'];

async function randomRun(seed: number, faults: boolean) {
  let s = seed;
  const rnd = () => (s = (s * 1103515245 + 12345) % 2147483648) / 2147483648;
  const pick = () => ALL[Math.floor(rnd() * 3)];
  const h = await createHost();
  const ids = [...ALL];
  const everLeader = new Set<string>();
  const firstVote = new Map<string, string | null>();
  const check = async () => {
    const views = await Promise.all(ALL.map((n) => h.node(n)));
    views.forEach((v, i) => {
      if (v!.role === 'leader') everLeader.add(ALL[i]);
      // no node votes twice: once set, votedFor never changes
      if (v!.votedFor !== null) {
        if (!firstVote.has(ALL[i])) firstVote.set(ALL[i], v!.votedFor);
        assert.equal(v!.votedFor, firstVote.get(ALL[i]));
      }
    });
    assert.ok(everLeader.size <= 1);
    for (const id of everLeader) assert.ok(views.filter((v) => v!.votedFor === id).length >= 2);
    for (const v of views) if (v!.leader !== null) assert.ok(everLeader.has(v!.leader));
    return views;
  };
  for (;;) {
    const fl = await h.inFlight();
    const opts = ids.length + fl.length;
    if (opts === 0) break;
    if (faults) {
      if (rnd() < 0.1) await h.giveUp(pick());
      if (rnd() < 0.1) await h.crash(pick());
      if (rnd() < 0.1) await h.recover(pick());
    }
    const k = Math.floor(rnd() * opts);
    if (k < ids.length) {
      await h.timeout(ids[k]);
      ids.splice(k, 1);
    } else await h.deliver(fl[k - ids.length].id);
    await check();
  }
  const views = await check();
  if (!faults && everLeader.size) for (const v of views) assert.ok(everLeader.has(v!.leader!));
}

test('random orders: safety', async () => {
  for (let i = 1; i < 2000; i++) await randomRun(i, false);
});

test('random orders with give-ups, crashes and recoveries: safety', async () => {
  for (let i = 1; i < 3000; i++) await randomRun(i, true);
});

test('crash and recover', async () => {
  const h = await createHost();
  assert.equal((await h.recover('n0')).ok, false);
  assert.equal((await h.crash('nX')).ok, false);
  await h.timeout('n0');
  await h.deliver((await h.inFlight()).find((m) => m.to === 'n1')!.id);
  await h.deliver((await h.inFlight()).find((m) => m.action === 'VoteReply')!.id);
  assert.equal((await h.node('n0'))!.role, 'leader');
  // n2 is down when n0's RequestVote and Leader arrive: it ignores both
  assert.deepEqual(await h.crash('n2'), { ok: true });
  assert.equal((await h.crash('n2')).ok, false);
  assert.equal((await h.timeout('n2')).ok, false);
  assert.equal((await h.giveUp('n2')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.node('n2'), { role: 'down', term: 0, votedFor: null, leader: null });
  assert.deepEqual(await h.recover('n2'), { ok: true });
  assert.deepEqual(await h.node('n2'), { role: 'follower', term: 0, votedFor: null, leader: null });
  // leader crashes and recovers as a follower, keeping term, vote and known leader
  await h.crash('n0');
  assert.deepEqual(await h.node('n0'), { role: 'down', term: 1, votedFor: 'n0', leader: 'n0' });
  await h.recover('n0');
  assert.deepEqual(await h.node('n0'), { role: 'follower', term: 1, votedFor: 'n0', leader: 'n0' });
  assert.equal((await h.timeout('n0')).ok, false);
  // n2 runs, but both others voted for n0
  assert.deepEqual(await h.timeout('n2'), { ok: true });
  await h.deliverAll();
  assert.equal((await h.node('n2'))!.role, 'candidate');
});

